// IsReservedBotInput mirrors the exact, prefix and menu-substring routing rules.
func IsReservedBotInput(text string) bool {
	if strings.HasPrefix(text, "/") {
		return true
	}
	for _, s := range BotCommandNames {
		if text == s || strings.HasPrefix(text, s+" ") {
			return true
		}
	}
	for _, s := range botCommandPrefixes {
		if strings.HasPrefix(text, s) {
			return true
		}
	}
	for _, s := range botCommandContains {
		if strings.Contains(text, s) {
			return true
		}
	}
	return false
}
